"App: ADB Application Manager Pro ? (build ?)": "App: ADB Application Manager Pro ? (build ?)",
"AppCleaner can clear the caches that no file access can reach (the \"Clear cache\" button of an app's Storage screen) by tapping through the system settings for you. For that it needs this app's accessibility service. The service only acts while AppCleaner is clearing caches: it opens the App info screen of one app after the other, taps Clear cache, and stops when the screen turns off or locks. A cover over the screen shows what it is doing, with a way to cancel. Nothing is read or sent anywhere. On Android 13 and newer, an app installed from a file may first need \"Allow restricted settings\" (App info of this app, the three dots menu).": "O AppCleaner pode limpar os caches que nenhum acesso a arquivos alcança (o botão «Limpar cache» da tela Armazenamento de um app) tocando por você nas configurações do sistema. Para isso, precisa do serviço de acessibilidade deste app. O serviço só age enquanto o AppCleaner limpa caches: abre a tela Informações do app de um app após o outro, toca em Limpar cache e para quando a tela apaga ou bloqueia. Uma cobertura sobre a tela mostra o que ele está fazendo, com um jeito de cancelar. Nada é lido nem enviado para lugar nenhum. No Android 13 e posterior, um app instalado de um arquivo pode precisar primeiro de «Permitir configurações restritas» (Informações do app deste app, menu de três pontos).",
