"Aurora Store is an open-source Play Store client. Automatic Play version detection is a planned follow-up (it needs anonymous Play authentication); for now this routes each app to its store page, opening Aurora Store when it's installed.": "A Aurora Store é um cliente de código aberto da Play Store. A detecção automática de versões na Play é uma melhoria planejada (exige autenticação anônima na Play); por enquanto, cada app é encaminhado para a página dele na loja, abrindo a Aurora Store quando ela estiver instalada.",
"Aurora Store: installed · Play Store: installed. Tap an app below to open its store page.": "Aurora Store: instalada · Play Store: instalada. Toque em um app abaixo para abrir a página dele na loja.",
