"Browser Use did not start the task.": "O Browser Use não iniciou a tarefa.",
"Browser Use failed before it had an answer.": "O Browser Use falhou antes de ter uma resposta.",
"Browser Use finished without an answer.": "O Browser Use terminou sem uma resposta.",
"Browser Use is the open-source browser agent; this is its hosted cloud, which has a free tier for new accounts. An Ask agent button starts a short browser task that looks the question up on the web: it can take a minute or two and uses a little credit. It is for the Ask agent buttons only, not a chat. Testing the key costs nothing.": "O Browser Use é o agente de navegador de código aberto; esta é a nuvem hospedada dele, que tem um nível gratuito para contas novas. Um botão Ask agent inicia uma tarefa curta no navegador que procura a pergunta na web: pode levar um ou dois minutos e usa um pouco de crédito. Serve só para os botões Ask agent, não é um chat. Testar a chave não custa nada.",
"Browser Use took too long (over 4 minutes). Try again later.": "O Browser Use demorou demais (mais de 4 minutos). Tente de novo mais tarde.",
"Browser Use was stopped before it had an answer.": "O Browser Use foi interrompido antes de ter uma resposta.",
"Browser automation. Needs Node and a Chromium download, which can be heavy on a phone.": "Automação de navegador. Requer o Node e o download do Chromium, que pode ser pesado em um telefone.",
