"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back.": "Alterar o tema e os overlays passa pelo shell. Conecte um deles em Modos de operação e volte.",
"Changing the theme and the overlays goes through the shell. Connect one of them in Working Modes, then come back. The colors in use now are shown without it.": "Alterar o tema e os overlays passa pelo shell. Conecte um deles em Modos de operação e volte. As cores em uso agora são exibidas mesmo sem ele.",
