"Claude Code": "Claude Code",
"Claude Pro or Max and a Google account login may only be used in the providers' own apps: Anthropic and Google do not allow other apps to use those logins. So the Terminal signs you in through the official command-line tools running in Termux, where the provider's own website login opens:": "O Claude Pro ou Max e o login com Conta do Google só podem ser usados nos apps dos próprios provedores: a Anthropic e o Google não permitem que outros apps usem esses logins. Por isso, o Terminal faz o seu login pelas ferramentas oficiais de linha de comando executadas no Termux, onde abre a página de login do próprio site do provedor:",
"Clean up what is not needed any more: superfluous files, the expendable data of apps, the leftovers of apps that are gone, and files that exist twice. Scan first, look at the list, take out what you want to keep, then delete. The four tools use the working mode of this app for the folders a normal app cannot read.": "Limpe o que não é mais necessário: arquivos supérfluos, dados descartáveis dos apps, sobras de apps que já não existem e arquivos que existem em duplicidade. Primeiro verifique, olhe a lista, tire o que quiser manter e depois apague. As quatro ferramentas usam o modo de operação deste app para as pastas que um app normal não consegue ler.",
"Clean — no engine flagged this file": "Limpo — nenhum mecanismo sinalizou este arquivo",
"Cleanup is simulated. Files are scanned and reported, but nothing is actually deleted.": "A limpeza é simulada. Os arquivos são verificados e informados, mas nada é realmente apagado.",
