"Crawl4AI": "Crawl4AI",
"Crawl4AI found no answer for this one. Try Web search, or another agent.": "O Crawl4AI não achou resposta para isto. Tente a busca na web ou outro agente.",
"Crawl4AI is the open-source web crawler; this is its hosted cloud. A new account gets free credits and a free monthly allowance, no card. An Ask agent button sends the question to its answer service, which searches the web, reads the pages and writes the answer. It is for the Ask agent buttons only, not a chat. The test spends one credit.": "O Crawl4AI é o rastreador web de código aberto; esta é a nuvem hospedada dele. Uma conta nova recebe créditos gratuitos e uma cota mensal gratuita, sem cartão. Um botão Ask agent envia a pergunta ao serviço de respostas dele, que pesquisa na web, lê as páginas e escreve a resposta. Serve só para os botões Ask agent, não é um chat. O teste gasta um crédito.",
