"Draw the app icons in the list with an icon pack you have installed (ADW, Nova, Apex and Go packs). Apps the pack does not cover get the pack's background and shape when it has one, and otherwise keep their own icon.": "Desenhar os ícones dos apps na lista com um pacote de ícones instalado por você (pacotes ADW, Nova, Apex e Go). Os apps que o pacote não cobre recebem o fundo e o formato do pacote, quando ele tem, e, caso contrário, mantêm o próprio ícone.",
"Droid-ify": "Droid-ify",
"DroidMind": "DroidMind",
"DroidMind is an MCP server: a tool that gives AI agents control of an Android device over ADB (apps, files, logs, screenshots). It is not a chat by itself.": "O DroidMind é um servidor MCP: uma ferramenta que dá a agentes de IA o controle de um dispositivo Android via ADB (apps, arquivos, logs, capturas de tela). Sozinho, ele não é um chat.",
"DroidMind is installed in Debian. Start it with: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Add it to your agent as an MCP server (its address is printed when it starts).": "O DroidMind está instalado no Debian. Inicie-o com: proot-distro login debian -- ~/.local/bin/droidmind --transport sse. Adicione-o ao seu agente como um servidor MCP (o endereço dele é exibido ao iniciar).",
