"EXPERT": "ESPECIALISTA",
"Each agent keeps this in its own file, the same way its official sign-in does, so two or more agents can carry the same server and either can be used with it. Codex keeps a remote server's token as an environment variable instead of in its file. Not tested against every version of every tool.": "Cada agente guarda isso no próprio arquivo, do mesmo modo que o login oficial dele, então dois ou mais agentes podem ter o mesmo servidor e qualquer um deles pode usá-lo. O Codex guarda o token de um servidor remoto como variável de ambiente, e não no arquivo dele. Não foi testado em todas as versões de todas as ferramentas.",
"Each shell keeps its own screen and stays open while you use other tabs: cd, export and variables carry over from one command to the next. Restart shell starts a fresh one.": "Cada shell mantém a própria tela e continua aberto enquanto você usa outras abas: cd, export e variáveis permanecem de um comando para o outro. Reiniciar shell inicia um novo.",
"Each wait is 600 seconds (10 minutes) at most.": "Cada espera é de no máximo 600 segundos (10 minutos).",
"Earlier certificates (the signing key was changed)": "Certificados anteriores (a chave de assinatura foi alterada)",
