"Errors only": "Somente erros",
"Every app in the F-Droid catalog, or in any of the known third-party repositories. Pick a repository, browse by category and install directly — downloads are checked against the repository's published SHA-256.": "Todos os apps do catálogo do F-Droid ou de qualquer repositório de terceiros conhecido. Escolha um repositório, navegue por categoria e instale diretamente — os downloads são verificados com o SHA-256 publicado pelo repositório.",
"Every app that is not enabled is saved.": "Todo app que não está ativado é salvo.",
"Every change goes into the history, so it can be reverted.": "Toda alteração vai para o histórico, então pode ser revertida.",
"Every level is hidden - tap the color key above to show some.": "Todos os níveis estão ocultos - toque na legenda de cores acima para exibir alguns.",
"Every palette has a light and a dark version": "Toda paleta tem uma versão clara e uma escura",
"Every setting here goes back to what SD Maid SE ships with.": "Todas as configurações aqui voltam ao que o SD Maid SE traz de fábrica.",
"Every source is off. Turn some on in Settings.": "Todas as fontes estão desativadas. Ative algumas nas Configurações.",
"Every uninstall, disable and restore, with one-tap undo": "Cada desinstalação, desativação e restauração, com desfazer em um toque",
"Everything is up to date": "Tudo está atualizado",
"Everything is up to date.": "Tudo está atualizado.",
"Exa": "Exa",
"Exa found no answer for this one. Try Web search, or another agent.": "O Exa não encontrou resposta para esta pergunta. Tente a pesquisa na web ou outro agente.",
"Exa is a search engine built for AI. Its answer service searches the web and writes a short answer that names its sources. A new account gets free credits. Testing the key makes one small search (a fraction of a cent). An Ask agent button sends it the question; nothing is sent until you press one.": "O Exa é um mecanismo de busca feito para IA. Seu serviço de respostas pesquisa na web e escreve uma resposta curta que cita as fontes. Uma conta nova ganha créditos grátis. Testar a chave faz uma pequena pesquisa (uma fração de centavo). Um botão de consulta ao agente envia a pergunta a ele; nada é enviado até você tocar em um.",
