"Found by reading the class names in the app's code on this phone; nothing is sent anywhere. Tracker list: Exodus Privacy, licensed ODbL 1.0. Code renamed by a shrinker (R8, ProGuard) or loaded later can hide a tracker, so a low number is not proof that there are none.": "Encontrados lendo os nomes das classes no código do app neste telefone; nada é enviado para lugar nenhum. Lista de rastreadores: Exodus Privacy, licenciada ODbL 1.0. Código renomeado por um reduzidor (R8, ProGuard) ou carregado depois pode esconder um rastreador, então um número baixo não prova que não existe nenhum.",
