"From File Manager: installing through a privileged backend, with this app's signature checks off. Android still verifies signatures itself: an APK whose signature it can't verify is signed with this app's key and installed, and an app signed by someone else can only be replaced after uninstalling it (you are asked first).": "No Gerenciador de arquivos: a instalação é feita por um back-end privilegiado, com as verificações de assinatura deste app desativadas. O Android ainda verifica as assinaturas por conta própria: um APK cuja assinatura ele não consegue verificar é assinado com a chave deste app e instalado, e um app assinado por outra pessoa só pode ser substituído depois de desinstalado (o app pergunta antes).",
