"Jan runs AI models on your computer, free. On the computer: Jan, Settings, Local API Server: set the host to 0.0.0.0 and start it, then enter the computer's address here (like http://192.168.1.20:1337/v1). There is no Android version of Jan.": "O Jan roda modelos de IA no seu computador, de graça. No computador: Jan, Configurações, Local API Server: defina o host como 0.0.0.0 e inicie-o; depois, informe aqui o endereço do computador (como http://192.168.1.20:1337/v1). Não existe versão do Jan para Android.",
