"Off: reading outside the current folder needs your OK.": "Desativado: ler fora da pasta atual exige a sua aprovação.",
"Off: the patches that work are applied and the failed ones are reported.": "Desativado: os patches que funcionam são aplicados e os que falham são informados.",
