"Ollama": "Ollama",
"Ollama (on-device)": "Ollama (no dispositivo)",
"Ollama is not running on this phone yet. Install it below, or enter the address of a computer that runs it.": "O Ollama ainda não está rodando neste telefone. Instale-o abaixo ou informe o endereço de um computador em que ele roda.",
"Ollama runs a coding model right on this phone: free, and offline once the model is downloaded. It is installed in Termux; small models (1.5B to 3B) run best on a phone. Ollama on a computer works too: let it listen on all addresses there, then enter the computer's address here (like 192.168.1.20:11434/v1).": "O Ollama executa um modelo de programação direto neste telefone: grátis e offline depois que o modelo é baixado. É instalado no Termux; modelos pequenos (1,5B a 3B) funcionam melhor em um telefone. O Ollama em um computador também funciona: deixe-o escutar em todos os endereços e digite aqui o endereço do computador (como 192.168.1.20:11434/v1).",
"On": "Ativado",
"On device": "No dispositivo",
"On this phone": "Neste telefone",
"On:": "Ativado:",
"One command at a time per shell; long output is trimmed on screen and in what is sent to an agent.": "Um comando por vez em cada shell; saídas longas são cortadas na tela e no que é enviado a um agente.",
"One file only": "Um único arquivo",
"One key for the whole app. The Installer's scan and Morphe Helper's scan both use it; neither asks for it again, they only point here when it is missing.": "Uma chave para o app inteiro. A verificação do Instalador e a do Morphe Helper usam essa chave; nenhuma pede de novo, só apontam para cá quando falta.",
"One more place to find apps": "Mais um lugar para encontrar apps",
"One package per line. Duplicate entries are removed automatically.": "Um pacote por linha. Entradas duplicadas são removidas automaticamente.",
"One source color, nine ways to turn it into a whole theme: the accent, the background, the cards and the text, in light and in dark. Choosing a style builds the theme from the source color below.": "Uma cor de origem, nove formas de transformá-la em um tema completo: o destaque, o fundo, os cartões e o texto, no claro e no escuro. Escolher um estilo cria o tema a partir da cor de origem abaixo.",
"Only AppCleaner uses it: it opens the system's App info screen of each app and taps Clear cache, for the caches no file access can reach. It does nothing else, never reads what is on the screen apart from those screens, and stops when the screen turns off.": "Só o AppCleaner usa: ele abre a tela Informações do app do sistema de cada app e toca em Limpar cache, para os caches que nenhum acesso a arquivos alcança. Não faz mais nada, nunca lê o que está na tela além dessas telas e para quando a tela apaga.",
"Only a marked block is written to these files; what you have in them stays, and running this again refreshes the block instead of adding another.": "Só um bloco marcado é gravado nestes arquivos; o que você já tem neles permanece, e executar isto de novo atualiza o bloco em vez de adicionar outro.",
"Only add sources you trust. A patch source decides what ends up inside your patched apps.": "Adicione apenas fontes em que você confia. Uma fonte de patches decide o que vai parar dentro dos seus apps modificados.",
"Only apps installed on this phone": "Somente apps instalados neste telefone",
"Only base": "Somente base",
"Only hidden files are here. Tick Show hidden files to see them.": "Aqui há apenas arquivos ocultos. Marque Mostrar arquivos ocultos para vê-los.",
"Only include common media files, documents and archives.": "Incluir apenas arquivos de mídia, documentos e arquivos compactados comuns.",
"Only list what would run for each app. Nothing is run.": "Apenas lista o que seria executado para cada app. Nada é executado.",
"Only patches for apps installed on this phone": "Somente patches de apps instalados neste telefone",
"Only split bundles are listed for this app. Turn on Allow split APK.": "Só pacotes divididos estão listados para este app. Ative Permitir APK dividido.",
"Only text and compiled XML files can be compared line by line": "Somente arquivos de texto e XML compilado podem ser comparados linha a linha",
"Only the app name you typed is sent.": "Apenas o nome do app digitado é enviado.",
"Only the lines written by the app you pick": "Somente as linhas gravadas pelo app escolhido",
"Only the selected apps are saved.": "Somente os apps selecionados são salvos.",
"Only the text of this app changes; names, paths and commands in code-style boxes keep their own font.": "Só o texto deste app muda; nomes, caminhos e comandos em caixas de código mantêm a própria fonte.",
"Only this sample question is sent to them: whether the Calculator package can be disabled.": "Somente esta pergunta de exemplo é enviada a ele: se o pacote Calculadora pode ser desativado.",
