"Pair and connect a Wear OS watch or any Android device over Wi-Fi or Bluetooth. Then you can manage its apps, send apps to it, read its log, browse its files and change its settings from here.": "Pareie e conecte um relógio Wear OS ou qualquer dispositivo Android por Wi-Fi ou Bluetooth. Depois, você pode gerenciar os apps dele, enviar apps para ele, ler o log, navegar pelos arquivos e alterar as configurações dele daqui.",
