"Perplexity": "Perplexity",
"Phone makers and apps add settings of their own.": "Fabricantes de telefones e apps adicionam configurações próprias.",
"Pick a .mpp patch bundle from storage. A local source never updates on its own: pick the new file when one comes out.": "Escolha um pacote de patches .mpp do armazenamento. Uma fonte local nunca se atualiza sozinha: escolha o arquivo novo quando sair.",
"Pick a Coding Agent in the Terminal first": "Escolha primeiro um agente de programação no Terminal",
"Pick a package file to read it and choose how to install it.": "Escolha um arquivo de pacote para lê-lo e decidir como instalá-lo.",
"Pick a package first": "Escolha um pacote primeiro",
"Pick an agent under Coding Agents to chat": "Escolha um agente em Agentes de código para conversar",
"Pick an agent, then the model and the effort (Low, Balanced or High: how hard it is asked to think). The first time, both start at a balanced choice, and the agent asks for what it needs (an API key, a server address, or a sign-in) and tests it before you start.": "Escolha um agente e depois o modelo e o esforço (Baixo, Equilibrado ou Alto: o quanto ele é solicitado a pensar). Na primeira vez, ambos começam em uma opção equilibrada, e o agente pede o que precisa (uma chave de API, um endereço de servidor ou um login) e testa isso antes de você começar.",
"Pick at least one agent": "Escolha pelo menos um agente",
"Pick at least one patch": "Escolha pelo menos um patch",
