"Termux does not take commands from other apps yet: run the command of step 3 in Termux, then test again.": "O Termux ainda não aceita comandos de outros apps: execute o comando da etapa 3 no Termux e teste de novo.",
"Termux is free. Get it from F-Droid or GitHub; the old Google Play build is not suitable.": "O Termux é gratuito. Baixe-o pelo F-Droid ou pelo GitHub; a versão antiga do Google Play não serve.",
