"The accessibility service is not ready": "O serviço de acessibilidade não está pronto",
"The accessibility service is not ready (it is not connected), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "O serviço de acessibilidade não está pronto (não está conectado), então os caches que só ele pode limpar permanecem. Depois, use «Limpar o resto com acessibilidade» no cartão do AppCleaner.",
"The accessibility service is not ready (it is off), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "O serviço de acessibilidade não está pronto (está desativado), então os caches que só ele pode limpar permanecem. Depois, use «Limpar o resto com acessibilidade» no cartão do AppCleaner.",
"The accessibility service is not ready (no consent given), so the caches that only it can clear stay. After this, use \"Clear the rest with accessibility\" on the AppCleaner card.": "O serviço de acessibilidade não está pronto (consentimento não dado), então os caches que só ele pode limpar permanecem. Depois, use «Limpar o resto com acessibilidade» no cartão do AppCleaner.",
"The account has no credit left, or a spending limit was reached.": "A conta está sem crédito, ou um limite de gastos foi atingido.",
