"The exclusions could not be read.": "Não foi possível ler as exclusões.",
"The extra button on every row of the Apps list. Choose what a tap on it does. Press and hold it on a row for a sheet with every action for that app.": "O botão extra em cada linha da lista de Apps. Escolha o que um toque nele faz. Mantenha-o pressionado em uma linha para uma folha com todas as ações daquele app.",
"The extra keys work like Termux's: ESC clears the line, TAB completes a file name, CTRL-C stops what is running, the arrows go through earlier commands and move the cursor, HOME and END jump in the line, and | / - ~ are there because phone keyboards hide them.": "As teclas extras funcionam como as do Termux: ESC limpa a linha, TAB completa um nome de arquivo, CTRL-C interrompe o que está em execução, as setas percorrem os comandos anteriores e movem o cursor, HOME e END saltam dentro da linha, e | / - ~ estão aí porque os teclados de celular os escondem.",
"The extraction could not start": "Não foi possível iniciar a extração",
"The file": "O arquivo",
"The file and its log are removed. The app on the phone is not touched.": "O arquivo e o registro dele são removidos. O app no telefone não é alterado.",
"The file chooser needs the app build": "O seletor de arquivos precisa da versão do app",
"The file is removed from this phone's storage, not just from the list. An Undo bar stays for a few seconds, and the file only goes for good once that bar is gone.": "O arquivo é removido do armazenamento do telefone, e não apenas da lista. Uma barra Desfazer fica visível por alguns segundos, e o arquivo só é excluído de vez quando essa barra some.",
"The file was saved, but it is not an app file (unknown). Choose another download in the browser.": "O arquivo foi salvo, mas não é um arquivo de app (desconhecido). Escolha outro download no navegador.",
