"The list of fonts is cleared": "A lista de fontes foi limpa",
"The lists are cut at 3000 entries each.": "As listas são cortadas em 3.000 itens cada.",
"The manifest does not ask for any extra library (no uses-library entry).": "O manifesto não pede nenhuma biblioteca extra (nenhuma entrada uses-library).",
"The name in code type is the key. It is the same on every phone that has the setting.": "O nome no tipo código é a chave. É o mesmo em todo telefone que tem a configuração.",
"The old code is gone. Anything you gave it to has to be given the new one.": "O código antigo não existe mais. Tudo a que você o deu precisa receber o novo.",
"The older storage permission some apps still check for.": "A permissão de armazenamento mais antiga que alguns apps ainda verificam.",
"The pairing code has 6 digits": "O código de pareamento tem 6 dígitos",
"The password is used only for this archive, only while it is open. It is never saved.": "A senha é usada somente para este arquivo, e somente enquanto ele está aberto. Ela nunca é salva.",
"The patch bundle may be damaged or made for a newer Morphe. Update the source in Sources.": "O pacote de patches pode estar danificado ou ter sido feito para um Morphe mais novo. Atualize a fonte em Fontes.",
"The patched APK is only saved. Install it from Patched APKs.": "O APK modificado só é salvo. Instale-o em APKs modificados.",
"The patched APK was deleted after the install.": "O APK modificado foi apagado depois da instalação.",
"The patcher could not be started": "Não foi possível iniciar o patcher",
"The patcher ran out of memory. Close other apps and try again, or turn on \"Strip unused native libraries\" in the patcher settings.": "O patcher ficou sem memória. Feche outros apps e tente de novo, ou ative «Remover bibliotecas nativas não usadas» nas configurações do patcher.",
"The patcher stopped": "O patcher parou",
"The patcher stops and nothing is saved.": "O patcher para e nada é salvo.",
"The patches could not be read": "Não foi possível ler os patches",
"The patches do not support this version of the app. Get a supported version with Morphe Helper, or turn on \"Patch unsupported versions\" in the patcher settings.": "Os patches não suportam esta versão do app. Obtenha uma versão compatível com o Morphe Helper, ou ative «Modificar versões sem suporte» nas configurações do patcher.",
"The paths could not be read.": "Não foi possível ler os caminhos.",
"The phone may still apply it. It is looked at again in a moment.": "O telefone ainda pode aplicá-lo. Ele será verificado de novo em instantes.",
"The phone may still apply it. The list is read again in a moment.": "O telefone ainda pode aplicá-lo. A lista é lida de novo em instantes.",
"The phone's browser": "O navegador do telefone",
"The project gives no description for this package.": "O projeto não traz descrição para este pacote.",
"The providers do not support Android officially: the tool may not run on every phone. The Terminal shows its exact messages when something fails.": "Os provedores não oferecem suporte oficial ao Android: a ferramenta pode não funcionar em todos os telefones. O Terminal mostra as mensagens exatas dela quando algo falha.",
"The pull did not finish": "A cópia não foi concluída",
"The push did not finish": "O envio não foi concluído",
"The quick brown fox jumps over the lazy dog.": "The quick brown fox jumps over the lazy dog.",
"The repository must be an https:// address": "O repositório deve ser um endereço https://",
"The request could not be sent": "Não foi possível enviar a solicitação",
"The request could not start": "Não foi possível iniciar a solicitação",
"The research agent behind every Ask agent button, and the one the Application Updater asks to find an app. It reads the web and weighs what it finds to answer: what a hidden setting, a permission, a process, a log line or an app is. It is not a coding agent and it never changes anything on the phone. Perplexity is the default: it searches the web by itself and names its sources. Its key is set up in the Command-Line Interface tab.": "O agente de pesquisa por trás de todo botão de consulta ao agente, e aquele a quem o Atualizador de apps pede para encontrar um app. Ele lê a web e pondera o que encontra para responder: o que é uma configuração oculta, uma permissão, um processo, uma linha de log ou um app. Não é um agente de programação e nunca altera nada no telefone. O Perplexity é o padrão: pesquisa na web sozinho e cita as fontes. A chave dele é configurada na aba Command-Line Interface.",
"The resolution the device draws at, width x height in pixels.": "A resolução em que o dispositivo desenha, largura x altura em pixels.",
"The round checkmark button (when apps are selected)": "O botão redondo com marca de seleção (quando há apps selecionados)",
"The scan failed: unknown error": "Falha na análise: erro desconhecido",
"The screen shows the settings of one app after the other for a moment while Clear cache is tapped for each app that still has a cache the files cannot reach. A cover shows what is happening, with a Cancel button. It stops if the screen turns off.": "A tela mostra por um momento as configurações de um app após o outro enquanto Limpar cache é tocado para cada app que ainda tem um cache que os arquivos não alcançam. Uma cobertura mostra o que está acontecendo, com um botão Cancelar. Para se a tela apagar.",
"The search could not start": "Não foi possível iniciar a busca",
"The search did not work.": "A busca falhou.",
"The search failed": "A busca falhou",
"The search failed.": "Falha na pesquisa.",
"The search failed: unknown error": "A busca falhou: erro desconhecido",
"The search took too long. Tap Find APKs to try again.": "A pesquisa demorou demais. Toque em Encontrar APKs para tentar de novo.",
"The service is off.": "O serviço está desativado.",
"The service is switched on but has not connected yet; turn it off and on again in the accessibility settings.": "O serviço está ativado, mas ainda não conectou; desative e ative de novo nas configurações de acessibilidade.",
"The setting's name, table and current value are sent to them.": "O nome, a tabela e o valor atual da configuração são enviados a eles.",
"The shell did not start": "O shell não iniciou",
