"Then allow this app to \"Run commands in Termux environment\" and test the connection. Termux setup in the Terminal settings walks you through it.": "Depois, conceda a este app a permissão “Run commands in Termux environment” e teste a conexão. A Configuração do Termux, nas configurações do Terminal, guia você por esse processo.",
