"These apps are uninstalled but their data folders are still on the phone. The data of the apps you tick is deleted for good.": "Estes apps estão desinstalados, mas as pastas de dados deles ainda estão no telefone. Os dados dos apps que você marcar são apagados de vez.",
"These apps are uninstalled. Without Root the app cannot see which of them still have data, so clearing all of them is safe but may find nothing for some. The data of the apps you tick is deleted for good.": "Estes apps estão desinstalados. Sem Root o app não consegue ver quais ainda têm dados, então limpar todos é seguro, mas pode não encontrar nada para alguns. Os dados dos apps que você marcar são apagados de vez.",
"These apps' releases live on sites this app can't check directly. Obtainium can track them.": "As versões destes apps ficam em sites que este app não consegue verificar diretamente. O Obtainium pode acompanhá-los.",
"These files are too different to compare line by line. View each one instead.": "Estes arquivos são diferentes demais para comparar linha a linha. Veja cada um separadamente.",
"They go on when the browser is closed. Pause keeps what was downloaded and Resume asks the site for the rest only (a site that cannot do that starts the file again).": "Continuam quando o navegador é fechado. Pausar mantém o que foi baixado e Retomar pede ao site só o resto (um site que não consegue isso recomeça o arquivo).",
"They will be skipped unless you patch anyway, which may fail or break the app.": "Serão ignorados, a menos que você modifique mesmo assim, o que pode falhar ou quebrar o app.",
