"This app cannot read storage. Grant All-files access, or choose a font file by hand (that needs no access).": "Este app não consegue ler o armazenamento. Conceda o acesso a todos os arquivos ou escolha um arquivo de fonte manualmente (isso não exige acesso).",
"This app does not ask for a particular touch screen, keyboard or navigation (it has no uses-configuration entry), so it runs with whatever this phone has.": "Este app não exige uma tela sensível ao toque, teclado ou navegação específicos (não tem entrada uses-configuration), então roda com o que este telefone tiver.",
"This app does not list any hardware or software features it needs (no uses-feature entries).": "Este app não lista nenhum recurso de hardware ou software de que precise (nenhuma entrada uses-feature).",
"This app has no activities.": "Este app não tem atividades.",
"This app may not run commands in Termux yet.": "Este app talvez ainda não possa executar comandos no Termux.",
"This app now has its own private ADB key. Tap the mode badge for details.": "Este app agora tem a própria chave ADB privada. Toque no selo do modo para ver os detalhes.",
"This app's code could not be read (it has none, or the file is not readable), so nothing can be said about trackers.": "Não foi possível ler o código deste app (ele não tem, ou o arquivo não é legível), então não dá para dizer nada sobre rastreadores.",
"This app's own authorization code. Nothing accepts it yet: it is kept here for later. It is made on this phone, stays on this phone, and you can replace it at any time.": "O código de autorização próprio deste app. Nada o aceita ainda: ele fica guardado aqui para depois. Ele é gerado neste celular, permanece neste celular e você pode substituí-lo a qualquer momento.",
"This app's own shell - no root, ADB or package manager.": "O shell próprio deste app - sem root, ADB nem gerenciador de pacotes.",
