"When deleting duplicates, SD Maid decides which file to keep by checking each criterion in order. The first criterion that produces a clear winner determines the result. Drag to reorder, tap to change mode.": "Ao apagar duplicatas, o SD Maid decide qual arquivo manter verificando cada critério em ordem. O primeiro critério que dá um vencedor claro determina o resultado. Arraste para reordenar, toque para mudar o modo.",
